      "titel": "69 n. Chr. – Das Jahr der vier Kaiser",
      "autor": "Gwyn Morgan",
      "jahr": "2006",
      "warum": "Rekonstruiert den Ablauf Woche für Woche und prüft Tacitus gegen die anderen Quellen."
